void ARKAudioProcessorEditor::drawLfoCurve(juce::Graphics& g, int x, int y, int width, int height, int lfoType)
{
    // ---- Background: deep black base ----
    g.setColour(juce::Colour(0xff0a0a0a));
    g.fillRoundedRectangle(x, y, width, height, 4.0f);

    // ---- Radial gradient: warm centre glow ----
    {
        juce::ColourGradient radial(
            juce::Colour(0xff1e1a0a),
            x + width * 0.5f, y + height * 0.5f,
            juce::Colour(0xff050505),
            x + 2.0f, y + 2.0f,
            true);
        g.setGradientFill(radial);
        g.fillRoundedRectangle(x + 1.0f, y + 1.0f, width - 2.0f, height - 2.0f, 4.0f);
    }

    // ---- Border: subtle gold tint ----
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.35f));
    g.drawRoundedRectangle(x, y, width, height, 4.0f, 1.0f);

    // ---- Grid lines: very faint ----
    g.setColour(juce::Colour(0xff2a2a2a).withAlpha(0.3f));
    for (int i = 1; i < 4; i++)
    {
        float yPos = y + (height * i / 4.0f);
        g.drawLine(x + 8, yPos, x + width - 8, yPos, 0.5f);
    }

    // ---- Centre line ----
    g.setColour(juce::Colour(0xff333333));
    g.drawLine(x + 8, y + height / 2.0f, x + width - 8, y + height / 2.0f, 0.8f);

    // ---- Build waveform path ----
    juce::Path lfo;
    const int   numCycles  = 3;
    const int   numPoints  = 300;
    const float startX     = x + 10;
    const float midY       = y + height / 2.0f;
    const float amplitude  = (height - 20) / 2.5f;
    const float curveWidth = width - 20;
    
    for (int i = 0; i < numPoints; i++)
    {
        float t     = (float)i / (float)(numPoints - 1);
        float xPos  = startX + t * curveWidth;
        float phase = std::fmod(t * numCycles, 1.0f);
        float yPos  = midY;

        switch (lfoType)
        {
            case 0:
                yPos += amplitude * std::sin(t * numCycles * juce::MathConstants<float>::twoPi);
                break;
            case 1:
                yPos += amplitude * (2.0f * phase - 1.0f);
                break;
            case 2:
                yPos += amplitude * (phase < 0.5f ? 1.0f : -1.0f);
                break;
            case 3:
                yPos += amplitude * (phase < 0.5f ? (4.0f * phase - 1.0f) : (3.0f - 4.0f * phase));
                break;
        }
        
        if (i == 0) lfo.startNewSubPath(xPos, yPos);
        else        lfo.lineTo(xPos, yPos);
    }

    // ---- Reflection: mirrored below centre, fading ----
    {
        juce::Path reflPath;
        for (int i = 0; i < numPoints; i++)
        {
            float t     = (float)i / (float)(numPoints - 1);
            float xPos  = startX + t * curveWidth;
            float phase = std::fmod(t * numCycles, 1.0f);
            float wave  = 0.0f;

            switch (lfoType)
            {
                case 0: wave = amplitude * std::sin(t * numCycles * juce::MathConstants<float>::twoPi); break;
                case 1: wave = amplitude * (2.0f * phase - 1.0f); break;
                case 2: wave = amplitude * (phase < 0.5f ? 1.0f : -1.0f); break;
                case 3: wave = amplitude * (phase < 0.5f ? (4.0f * phase - 1.0f) : (3.0f - 4.0f * phase)); break;
            }

            float yPos = midY - wave * 0.45f + 4.0f;
            if (i == 0) reflPath.startNewSubPath(xPos, yPos);
            else        reflPath.lineTo(xPos, yPos);
        }

        g.setColour(juce::Colour(0xffD4A017).withAlpha(0.04f));
        g.strokePath(reflPath, juce::PathStrokeType(6.0f));
        g.setColour(juce::Colour(0xffD4A017).withAlpha(0.12f));
        g.strokePath(reflPath, juce::PathStrokeType(1.2f));
    }

    // ---- Main waveform: 3 glow layers + sharp core ----
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.08f));
    g.strokePath(lfo, juce::PathStrokeType(10.0f));
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.18f));
    g.strokePath(lfo, juce::PathStrokeType(5.0f));
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.45f));
    g.strokePath(lfo, juce::PathStrokeType(2.5f));
    g.setColour(juce::Colour(0xffFFD84D));
    g.strokePath(lfo, juce::PathStrokeType(1.0f));
}

void ARKAudioProcessorEditor::drawVelocityCurve(juce::Graphics& g, int x, int y, int width, int height, float curve)
{
    // ---- Background: deep black base ----
    g.setColour(juce::Colour(0xff0a0a0a));
    g.fillRoundedRectangle(x, y, width, height, 4.0f);

    // ---- Radial gradient: warm centre glow ----
    {
        juce::ColourGradient radial(
            juce::Colour(0xff1e1a0a),
            x + width * 0.5f, y + height * 0.5f,
            juce::Colour(0xff050505),
            x + 2.0f, y + 2.0f,
            true);
        g.setGradientFill(radial);
        g.fillRoundedRectangle(x + 1.0f, y + 1.0f, width - 2.0f, height - 2.0f, 4.0f);
    }

    // ---- Border: subtle gold tint ----
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.35f));
    g.drawRoundedRectangle(x, y, width, height, 4.0f, 1.0f);

    // ---- Grid lines: very faint ----
    g.setColour(juce::Colour(0xff2a2a2a).withAlpha(0.3f));
    for (int i = 1; i < 4; i++)
    {
        float yPos = y + (height * i / 4.0f);
        g.drawLine(x + 6, yPos, x + width - 6, yPos, 0.5f);
        float xPos = x + (width * i / 4.0f);
        g.drawLine(xPos, y + 6, xPos, y + height - 6, 0.5f);
    }

    // ---- Build velocity response curve ----
    juce::Path curvePath;
    const int numPoints = 200;
    const float startX = x + 6;
    const float startY = y + height - 6;
    const float curveWidth = width - 12;
    const float curveHeight = height - 12;

    for (int i = 0; i < numPoints; i++)
    {
        float t = (float)i / (float)(numPoints - 1);
        float xPos = startX + t * curveWidth;
        
        // Apply curve shaping
        float response;
        if (curve == 0.0f)
        {
            response = t; // Linear
        }
        else if (curve > 0.0f)
        {
            // Exponential (harder velocities get more output)
            float exp = 1.0f + (curve / 100.0f) * 3.0f;
            response = std::pow(t, exp);
        }
        else
        {
            // Logarithmic (softer velocities get more output)
            float exp = 1.0f / (1.0f - (curve / 100.0f) * 0.7f);
            response = std::pow(t, exp);
        }
        
        float yPos = startY - response * curveHeight;
        
        if (i == 0) curvePath.startNewSubPath(xPos, yPos);
        else        curvePath.lineTo(xPos, yPos);
    }

    // ---- 3 glow layers + sharp core ----
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.08f));
    g.strokePath(curvePath, juce::PathStrokeType(10.0f));
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.18f));
    g.strokePath(curvePath, juce::PathStrokeType(5.0f));
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.45f));
    g.strokePath(curvePath, juce::PathStrokeType(2.5f));
    g.setColour(juce::Colour(0xffFFD84D));
    g.strokePath(curvePath, juce::PathStrokeType(1.0f));
    
    // ---- Control points at start and end ----
    auto drawControlPoint = [&](float cx, float cy)
    {
        g.setColour(juce::Colour(0xffD4A017).withAlpha(0.3f));
        g.fillEllipse(cx - 5, cy - 5, 10, 10);
        g.setColour(juce::Colour(0xffFFD84D));
        g.fillEllipse(cx - 2.5f, cy - 2.5f, 5, 5);
    };
    drawControlPoint(startX, startY);
    drawControlPoint(startX + curveWidth, y + 6);
}

void ARKAudioProcessorEditor::drawNoteCurve(juce::Graphics& g, int x, int y, int width, int height, float curve)
{
    // ---- Background: deep black base ----
    g.setColour(juce::Colour(0xff0a0a0a));
    g.fillRoundedRectangle(x, y, width, height, 4.0f);

    // ---- Radial gradient: warm centre glow ----
    {
        juce::ColourGradient radial(
            juce::Colour(0xff1e1a0a),
            x + width * 0.5f, y + height * 0.5f,
            juce::Colour(0xff050505),
            x + 2.0f, y + 2.0f,
            true);
        g.setGradientFill(radial);
        g.fillRoundedRectangle(x + 1.0f, y + 1.0f, width - 2.0f, height - 2.0f, 4.0f);
    }

    // ---- Border: subtle gold tint ----
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.35f));
    g.drawRoundedRectangle(x, y, width, height, 4.0f, 1.0f);

    // ---- Grid lines: very faint ----
    g.setColour(juce::Colour(0xff2a2a2a).withAlpha(0.3f));
    for (int i = 1; i < 4; i++)
    {
        float yPos = y + (height * i / 4.0f);
        g.drawLine(x + 6, yPos, x + width - 6, yPos, 0.5f);
        float xPos = x + (width * i / 4.0f);
        g.drawLine(xPos, y + 6, xPos, y + height - 6, 0.5f);
    }

    // ---- Centre line (0 modulation) ----
    g.setColour(juce::Colour(0xff333333));
    g.drawLine(x + 6, y + height / 2.0f, x + width - 6, y + height / 2.0f, 0.8f);

    // ---- Build note tracking curve (diagonal line showing keyboard tracking) ----
    juce::Path curvePath;
    const int numPoints = 200;
    const float startX = x + 6;
    const float centerY = y + height / 2.0f;
    const float curveWidth = width - 12;
    const float curveHeight = (height - 12) / 2.0f;

    for (int i = 0; i < numPoints; i++)
    {
        float t = (float)i / (float)(numPoints - 1);
        float xPos = startX + t * curveWidth;
        
        // Note curve shows how pitch affects modulation
        // Typically a diagonal line from bottom-left to top-right
        float modAmount = (t - 0.5f) * 2.0f; // -1 to +1
        
        // Apply curve shaping
        if (curve != 0.0f)
        {
            float shaped = std::pow(std::abs(modAmount), 1.0f + curve / 100.0f);
            modAmount = modAmount < 0 ? -shaped : shaped;
        }
        
        float yPos = centerY - modAmount * curveHeight;
        
        if (i == 0) curvePath.startNewSubPath(xPos, yPos);
        else        curvePath.lineTo(xPos, yPos);
    }

    // ---- 3 glow layers + sharp core ----
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.08f));
    g.strokePath(curvePath, juce::PathStrokeType(10.0f));
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.18f));
    g.strokePath(curvePath, juce::PathStrokeType(5.0f));
    g.setColour(juce::Colour(0xffD4A017).withAlpha(0.45f));
    g.strokePath(curvePath, juce::PathStrokeType(2.5f));
    g.setColour(juce::Colour(0xffFFD84D));
    g.strokePath(curvePath, juce::PathStrokeType(1.0f));
}

