    //
    // LEFT COLUMN  (x=880..1140):
    //   Row 0: LP / HP / BP / NOTCH type buttons
    //   Row 1: CUTOFF, RES, DRIVE
    //   Row 2: ENV AMT, LFO AMT
    //
    // Vertical divider at x=1145
    //
    // RIGHT COLUMN (x=1153..1381):
    //   Top:    filter response display  (drawn in paint())
    //   Bottom: ATK, DCY, SUS, REL
    // =========================================================================

    const int fPanelX  = 880;   // left column start
    const int fRightX  = 1153;  // right column start

    // --- Filter character dropdown ---
    filterCharacterBox.setBounds(880, 83, 237, 20);

    // --- Type buttons (LP HP BP NOTCH) --- shifted down 30px for preset bar ---
    const int fBtnY   = 118;
    const int fBtnW   = 56;
    const int fBtnH   = 24;
    const int fBtnGap = 3;

    filterLpBtn.setBounds   (fPanelX,                          fBtnY, fBtnW, fBtnH);
    filterHpBtn.setBounds   (fPanelX + (fBtnW + fBtnGap),      fBtnY, fBtnW, fBtnH);
    filterBpBtn.setBounds   (fPanelX + (fBtnW + fBtnGap) * 2,  fBtnY, fBtnW, fBtnH);
    filterNotchBtn.setBounds(fPanelX + (fBtnW + fBtnGap) * 3,  fBtnY, fBtnW, fBtnH);

    // --- Row 1: CUTOFF, RES, DRIVE ---
    const int fRow1Y = 150;

    filterCutoff.setBounds        (fPanelX,                  fRow1Y, knobSize, knobSize);
    filterCutoffLabel.setBounds   (fPanelX,                  fRow1Y + knobSize + 2, knobSize, 12);
    filterResonance.setBounds     (fPanelX + knobSpacing,    fRow1Y, knobSize, knobSize);
    filterResonanceLabel.setBounds(fPanelX + knobSpacing,    fRow1Y + knobSize + 2, knobSize, 12);
    filterDrive.setBounds         (fPanelX + knobSpacing * 2, fRow1Y, knobSize, knobSize);
    filterDriveLabel.setBounds    (fPanelX + knobSpacing * 2, fRow1Y + knobSize + 2, knobSize, 12);

    // --- Row 2: ENV AMT, LFO AMT ---
    const int fRow2Y = fRow1Y + 80;

    filterEnvAmount.setBounds     (fPanelX,               fRow2Y, knobSize, knobSize);
    filterEnvAmountLabel.setBounds(fPanelX,               fRow2Y + knobSize + 2, knobSize, 12);
    filterLfoAmount.setBounds     (fPanelX + knobSpacing, fRow2Y, knobSize, knobSize);
    filterLfoAmountLabel.setBounds(fPanelX + knobSpacing, fRow2Y + knobSize + 2, knobSize, 12);
    filterFmFilter.setBounds      (fPanelX + knobSpacing * 2, fRow2Y, knobSize, knobSize);
    filterFmFilterLabel.setBounds (fPanelX + knobSpacing * 2, fRow2Y + knobSize + 2, knobSize, 12);

    // --- Right column: ADSR shifted down 30px too ---
    const int fEnvY = 252;

    filterAttack.setBounds       (fRightX,                   fEnvY, knobSize, knobSize);
    filterAttackLabel.setBounds  (fRightX,                   fEnvY + knobSize + 2, knobSize, 12);
    filterDecay.setBounds        (fRightX + knobSpacing,     fEnvY, knobSize, knobSize);
    filterDecayLabel.setBounds   (fRightX + knobSpacing,     fEnvY + knobSize + 2, knobSize, 12);
    filterSustain.setBounds      (fRightX + knobSpacing * 2, fEnvY, knobSize, knobSize);
    filterSustainLabel.setBounds (fRightX + knobSpacing * 2, fEnvY + knobSize + 2, knobSize, 12);
    filterRelease.setBounds      (fRightX + knobSpacing * 3, fEnvY, knobSize, knobSize);
    filterReleaseLabel.setBounds (fRightX + knobSpacing * 3, fEnvY + knobSize + 2, knobSize, 12);

    // =========================================================================
